const ACCOUNT_ID = 'a706de72-ef6f-11ed-ae54-78ac440eef32';

// Sellerboard rechnet tagesgenau in UTC. Lokale Mitternacht (CEST = UTC+2) liegt im VORTAG (UTC)
// -> deshalb den Tag strikt aus UTC ableiten, sonst pollt man stundenlang ein totes Gestern.
const DAY = 86400;
const todayUtc = Math.floor(Date.now() / 1000 / DAY) * DAY;
const yesterdayUtc = todayUtc - DAY;

return [{ json: {
  tool: 'dashboard_period',
  arguments: {
    account_id: ACCOUNT_ID,
    periods: [{ start: todayUtc, end: todayUtc, compare_to_start: yesterdayUtc, compare_to_end: yesterdayUtc }]
  }
}}];

const r = $input.first().json;
if (!r.ok) throw new Error('Sellerboard-Call fehlgeschlagen: ' + r.error);

const period = r.payload?.result?.[0] || {};
const info = period.data?.Info || {};
const cmp = period.compare || {};
const fees = Object.fromEntries((period.data?.AmazonFeeDetails || []).map(f => [f.fee, f.sum]));

const kpi = {
  zeitpunkt: new Date().toISOString(),
  tagUtc: r.payload?.resolvedPeriods?.[0]?.from || null,
  umsatz: info.Sales ?? 0,
  einheiten: info.Units ?? 0,
  bestellungen: info.Orders ?? 0,
  erstattungen: info.Refunds ?? 0,
  nettogewinn: info.NetProfit ?? 0,
  marge_pct: info.Margin ?? null,
  roi_pct: info.ROI ?? null,
  werbekosten: info.Advertising ?? 0,
  umsatz_ppc: info.SalesPPC ?? 0,
  umsatz_organisch: info.SalesOrganic ?? 0,
  real_acos_pct: info.RealACOS ?? null,
  tacos_pct: info.Sales ? Math.round(Math.abs(info.Advertising || 0) / info.Sales * 1000) / 10 : null,
  amazon_gebuehren: info.AmazonFees ?? 0,
  produktkosten: info.ProductCosts ?? 0,
  est_payout: info.EstPayout ?? 0,
  klicks: info.Clicks ?? 0,
  sessions: info.sessions ?? 0,
  gestern_umsatz: cmp.Sales ?? null,
  gestern_bestellungen: cmp.Orders ?? null,
  gestern_nettogewinn: cmp.NetProfit ?? null,
  delta_umsatz_pct: cmp.Sales_delta ?? null,
  delta_bestellungen_pct: cmp.Orders_delta ?? null,
  gebuehr_fba: fees.FBAPerUnitFulfillmentFee ?? 0,
  gebuehr_storage: fees.FBAStorageFee ?? 0
};

// ===== "Push"-Ersatz: Delta gegen den letzten Lauf =====
const store = $getWorkflowStaticData('global');
const vorher = store.letzteKpi || {};
const gleicherTag = vorher.tagUtc === kpi.tagUtc;
const neueBestellungen = gleicherTag ? kpi.bestellungen - (vorher.bestellungen ?? 0) : kpi.bestellungen;
const neuerUmsatz = gleicherTag ? kpi.umsatz - (vorher.umsatz ?? 0) : kpi.umsatz;
store.letzteKpi = kpi;

// ===== Alarmregeln (anpassen) =====
const regeln = [];
if (kpi.real_acos_pct !== null && kpi.werbekosten < -20 && kpi.real_acos_pct > 35) regeln.push(`ACoS ${kpi.real_acos_pct.toFixed(1)} % bei ${Math.abs(kpi.werbekosten).toFixed(2)} EUR Spend`);
if (kpi.umsatz > 150 && kpi.nettogewinn < 0) regeln.push(`Netto ${kpi.nettogewinn.toFixed(2)} EUR bei ${kpi.umsatz.toFixed(2)} EUR Umsatz`);
if (kpi.erstattungen >= 3) regeln.push(`${kpi.erstattungen} Erstattungen heute`);
const h = new Date().getUTCHours();
if (h >= 14 && kpi.delta_umsatz_pct !== null && kpi.delta_umsatz_pct < -60) regeln.push(`Umsatz ${kpi.delta_umsatz_pct.toFixed(0)} % vs. gestern (Stand ${h}:00 UTC)`);

const message = [
  `*Sellerboard ${kpi.tagUtc}* (Stand ${new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' })})`,
  `Umsatz *${kpi.umsatz.toFixed(2)} EUR* · ${kpi.bestellungen} Bestellungen · ${kpi.einheiten} Einheiten`,
  `Netto *${kpi.nettogewinn.toFixed(2)} EUR* · Marge ${kpi.marge_pct === null ? '–' : kpi.marge_pct.toFixed(1) + ' %'} · ACoS ${kpi.real_acos_pct === null ? '–' : kpi.real_acos_pct.toFixed(1) + ' %'} · TACoS ${kpi.tacos_pct === null ? '–' : kpi.tacos_pct + ' %'}`,
  `Letzte Stunde: +${neueBestellungen} Bestellungen / +${neuerUmsatz.toFixed(2)} EUR`,
  `Gestern gesamt: ${kpi.gestern_umsatz ?? '–'} EUR / ${kpi.gestern_bestellungen ?? '–'} Bestellungen / Netto ${kpi.gestern_nettogewinn ?? '–'} EUR`,
  regeln.length ? `:rotating_light: *Alarm:* ${regeln.join(' | ')}` : ''
].filter(Boolean).join('\n');

return [{ json: { ...kpi, neue_bestellungen_1h: neueBestellungen, neuer_umsatz_1h: neuerUmsatz, alarm: regeln.length > 0, alarm_grund: regeln.join(' | '), message } }];
